sale.addEventListener('mousedown',function(e){if(e.button!==0||Date.now()-touchAt<700)return;cancelMouse();var b=btn(e.target);if(!b||!b._promoProduct||b.disabled)return;mouse={b:b,x:e.clientX,y:e.clientY};mtimer=setTimeout(function(){if(!mouse)return;suppressClick(b);openActions(b._promoProduct);},500);},false);
