function checkedHistory(list){if(!Array.isArray(list)||list.length>100000)throw Error('Ungültige Verkaufsliste');var ids={};return list.map(function(t){if(!t||!safeText(t.id,200)||!t.id||Object.prototype.hasOwnProperty.call(ids,t.id)||!safeText(t.date,10)||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||!Array.isArray(t.items)||t.items.length>100||!integer(t.out,0,10000000)||!integer(t.back,0,10000000)||!integer(t.deposit,0,100000000)||!integer(t.drinkSum,0,9007199254740991)||!integer(t.total,-9007199254740991,9007199254740991)||!integer(t.cash,0,9007199254740991)||!integer(t.change,0,9007199254740991))throw Error('Ungültiger Verkauf');ids[t.id]=true;var itemIds={},sum=0;var items=t.items.map(function(p){if(!p||!safeText(p.id,101)||!/^g[\w-]{1,100}$/.test(p.id)||Object.prototype.hasOwnProperty.call(itemIds,p.id)||!safeText(p.name,40)||!p.name.trim()||!integer(p.qty,1,10000000)||!integer(p.price,0,100000000))throw Error('Ungültige Verkaufsposition');itemIds[p.id]=true;var line=validatedSaleItem(p);sum+=lineRevenue(line);return line;});var gratuity=t.tip===undefined?0:t.tip,base=sum+(t.out-t.back)*t.deposit;if(!integer(gratuity,0,100000000)||(gratuity>0&&base<=0)||sum!==t.drinkSum||base+gratuity!==t.total||(t.total>0?(t.cash<t.total||t.change!==t.cash-t.total):(t.cash!==0||t.change!==-t.total)))throw Error('Verkaufsbeträge stimmen nicht überein');return {id:t.id,date:t.date,timestamp:safeText(t.timestamp,50)?t.timestamp:'',localTime:safeText(t.localTime,20)?t.localTime:'',device:safeText(t.device,40)?t.device:'Kasse 1',items:items,drinkSum:t.drinkSum,out:t.out,back:t.back,deposit:t.deposit,tip:gratuity,total:t.total,cash:t.cash,change:t.change};});}
